package com.google.gson.internal.bind;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import com.google.gson.JsonToken;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import java.io.*;
import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class JsonTreeReader_skipValue_TriageGen1Test {

    private JsonTreeReader jsonTreeReader;

    @Before
    public void setup() throws IOException {
        JsonElement jsonElement = JsonElement.jsonNull();
        jsonTreeReader = new JsonTreeReader(jsonElement);
    }

    @Test
    public void testSkipValue_Name() throws IOException {
        // Set the peek value to NAME
        jsonTreeReader.peekValue(JsonToken.NAME);
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 2]);
    }

    @Test
    public void testSkipValue_Name_Name() throws IOException {
        // Set the peek value to NAME
        jsonTreeReader.peekValue(JsonToken.NAME);
        jsonTreeReader.skipValue();
        // Set the peek value to NAME again
        jsonTreeReader.peekValue(JsonToken.NAME);
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 2]);
    }

    @Test
    public void testSkipValue_Name_Value() throws IOException {
        // Set the peek value to NAME
        jsonTreeReader.peekValue(JsonToken.NAME);
        jsonTreeReader.skipValue();
        // Set the peek value to VALUE
        jsonTreeReader.peekValue(JsonToken.VALUE);
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 2]);
    }

    @Test
    public void testSkipValue_Value() throws IOException {
        // Set the peek value to VALUE
        jsonTreeReader.peekValue(JsonToken.VALUE);
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_Name_PopStack() throws IOException {
        // Set the peek value to NAME
        jsonTreeReader.peekValue(JsonToken.NAME);
        jsonTreeReader.skipValue();
        jsonTreeReader.popStack();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_Value_PopStack() throws IOException {
        // Set the peek value to VALUE
        jsonTreeReader.peekValue(JsonToken.VALUE);
        jsonTreeReader.skipValue();
        jsonTreeReader.popStack();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_NullPathNames() throws IOException {
        jsonTreeReader.skipValue();
        assertEquals("null", jsonTreeReader.pathNames[jsonTreeReader.stackSize - 1]);
    }

    @Test
    public void testSkipValue_NullPathIndices() throws IOException {
        jsonTreeReader.skipValue();
        assertEquals(1, jsonTreeReader.pathIndices[jsonTreeReader.stackSize - 1]);
    }
}
